import { afterEach, describe, expect, test } from "bun:test";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";

const cli = join(import.meta.dir, "..", "src", "cli.ts");
const temporaryDirectories: string[] = [];

async function makeDatabasePath(): Promise<string> {
  const directory = await mkdtemp(join(tmpdir(), "taskboard-test-"));
  temporaryDirectories.push(directory);
  return join(directory, "tasks.json");
}

function invoke(database: string, ...args: string[]) {
  const result = Bun.spawnSync(["bun", "run", cli, ...args], {
    env: { ...process.env, TASKBOARD_FILE: database },
    stdout: "pipe",
    stderr: "pipe",
  });
  return {
    exitCode: result.exitCode,
    stdout: result.stdout.toString(),
    stderr: result.stderr.toString(),
  };
}

afterEach(async () => {
  await Promise.all(temporaryDirectories.splice(0).map((directory) => rm(directory, { recursive: true })));
});

describe("taskboard CLI", () => {
  test("persists tasks, normalizes tags, filters, and keeps ids stable", async () => {
    const database = await makeDatabasePath();
    const first = invoke(database, "add", "--title", " First ", "--tags", "Work, work,URGENT", "--due", "2020-02-29");
    expect(first.exitCode).toBe(0);
    expect(JSON.parse(first.stdout)).toMatchObject({ id: 1, title: "First", status: "open", tags: ["work", "urgent"] });

    expect(JSON.parse(invoke(database, "add", "--title", "Second").stdout).id).toBe(2);
    expect(JSON.parse(invoke(database, "list", "--status", "open", "--tag", "WORK").stdout).map((task: { id: number }) => task.id)).toEqual([1]);

    const completed = JSON.parse(invoke(database, "done", "1").stdout);
    const completedAgain = JSON.parse(invoke(database, "done", "1").stdout);
    expect(completed.status).toBe("done");
    expect(completedAgain.completedAt).toBe(completed.completedAt);

    expect(invoke(database, "delete", "2").exitCode).toBe(0);
    expect(JSON.parse(invoke(database, "add", "--title", "Third").stdout).id).toBe(3);
  });

  test("applies overdue semantics and calculates stats", async () => {
    const database = await makeDatabasePath();
    invoke(database, "add", "--title", "Old", "--due", "2000-01-01");
    invoke(database, "add", "--title", "Boundary", "--due", "2100-01-01");
    invoke(database, "done", "1");

    expect(JSON.parse(invoke(database, "list", "--overdue", "2100-01-01").stdout)).toEqual([]);
    expect(JSON.parse(invoke(database, "stats").stdout)).toEqual({ total: 2, open: 1, done: 1, overdue: 0 });
  });

  test("rejects bad input and never replaces a malformed database", async () => {
    const database = await makeDatabasePath();
    const invalidDate = invoke(database, "add", "--title", "Bad", "--due", "2023-02-29");
    expect(invalidDate.exitCode).not.toBe(0);
    expect(invalidDate.stdout).toBe("null\n");

    await writeFile(database, "not json\n");
    const malformed = invoke(database, "add", "--title", "Would overwrite");
    expect(malformed.exitCode).not.toBe(0);
    expect(await readFile(database, "utf8")).toBe("not json\n");
  });
});

#!/usr/bin/env bun

import { open, readFile, rename, unlink } from "node:fs/promises";
import { basename, dirname, join } from "node:path";

type Status = "open" | "done";

interface Task {
  id: number;
  title: string;
  status: Status;
  createdAt: string;
  tags: string[];
  due?: string;
  completedAt?: string;
}

interface Database {
  nextId: number;
  tasks: Task[];
}

class CliError extends Error {}

const databasePath = process.env.TASKBOARD_FILE || join(process.cwd(), ".taskboard.json");

function fail(message: string): never {
  throw new CliError(message);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isDate(value: unknown): value is string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;

  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(5, 7));
  const day = Number(value.slice(8, 10));
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  return month >= 1 && month <= 12 && day >= 1 && day <= daysInMonth[month - 1]!;
}

function requireDate(value: string, label: string): string {
  if (!isDate(value)) fail(`${label} must be a valid date in YYYY-MM-DD format`);
  return value;
}

function isIsoTimestamp(value: unknown): value is string {
  if (typeof value !== "string") return false;
  const time = Date.parse(value);
  return Number.isFinite(time) && new Date(time).toISOString() === value;
}

function normalizeTag(tag: string): string {
  return tag.trim().toLocaleLowerCase();
}

function normalizeTags(value: string): string[] {
  const tags: string[] = [];
  const seen = new Set<string>();

  for (const rawTag of value.split(",")) {
    const tag = normalizeTag(rawTag);
    if (tag !== "" && !seen.has(tag)) {
      tags.push(tag);
      seen.add(tag);
    }
  }

  return tags;
}

function validateDatabase(value: unknown): Database {
  if (!isRecord(value) || !Number.isSafeInteger(value.nextId) || (value.nextId as number) < 1 || !Array.isArray(value.tasks)) {
    fail("database has an invalid structure");
  }

  const ids = new Set<number>();
  let greatestId = 0;

  for (const candidate of value.tasks) {
    if (!isRecord(candidate)) fail("database contains an invalid task");

    const { id, title, status, createdAt, tags, due, completedAt } = candidate;
    if (!Number.isSafeInteger(id) || (id as number) < 1 || ids.has(id as number)) {
      fail("database contains an invalid or duplicate task id");
    }
    if (typeof title !== "string" || title.trim() === "") fail("database contains an invalid task title");
    if (status !== "open" && status !== "done") fail("database contains an invalid task status");
    if (!isIsoTimestamp(createdAt)) fail("database contains an invalid createdAt timestamp");
    if (!Array.isArray(tags) || tags.some((tag) => typeof tag !== "string" || tag === "" || normalizeTag(tag) !== tag)) {
      fail("database contains invalid task tags");
    }
    if (new Set(tags).size !== tags.length) fail("database contains duplicate task tags");
    if (due !== undefined && !isDate(due)) fail("database contains an invalid due date");
    if (status === "done" && !isIsoTimestamp(completedAt)) fail("database contains an invalid completedAt timestamp");
    if (status === "open" && completedAt !== undefined) fail("database contains an invalid completedAt timestamp");

    ids.add(id as number);
    greatestId = Math.max(greatestId, id as number);
  }

  if ((value.nextId as number) <= greatestId) fail("database nextId does not follow existing task ids");
  return value as unknown as Database;
}

async function loadDatabase(): Promise<Database> {
  let contents: string;
  try {
    contents = await readFile(databasePath, "utf8");
  } catch (error) {
    if (isRecord(error) && error.code === "ENOENT") return { nextId: 1, tasks: [] };
    throw error;
  }

  let value: unknown;
  try {
    value = JSON.parse(contents);
  } catch {
    fail("database is not valid JSON");
  }
  return validateDatabase(value);
}

async function saveDatabase(database: Database): Promise<void> {
  const directory = dirname(databasePath);
  const temporaryPath = join(
    directory,
    `.${basename(databasePath)}.${process.pid}.${crypto.randomUUID()}.tmp`,
  );
  let handle: Awaited<ReturnType<typeof open>> | undefined;

  try {
    handle = await open(temporaryPath, "wx", 0o600);
    await handle.writeFile(`${JSON.stringify(database, null, 2)}\n`, "utf8");
    await handle.sync();
    await handle.close();
    handle = undefined;
    await rename(temporaryPath, databasePath);
  } catch (error) {
    if (handle) await handle.close().catch(() => undefined);
    await unlink(temporaryPath).catch(() => undefined);
    throw error;
  }
}

function parseOptions(
  args: string[],
  allowed: ReadonlySet<string>,
): Map<string, string> {
  const options = new Map<string, string>();

  for (let index = 0; index < args.length; index += 2) {
    const flag = args[index];
    if (!flag?.startsWith("--") || !allowed.has(flag)) fail(`unknown flag: ${flag ?? ""}`);
    if (options.has(flag)) fail(`duplicate flag: ${flag}`);
    const value = args[index + 1];
    if (value === undefined || value.startsWith("--")) fail(`missing value for ${flag}`);
